# First repair: rerun failed tasks with a new parameter value
databricks jobs repair-run --json '{
  "run_id": 987654,
  "rerun_all_failed_tasks": true,
  "job_parameters": {"run_date": "2026-11-03"}
}'

# Second repair of the same run: pass the latest repair_id
databricks jobs repair-run --json '{
  "run_id": 987654,
  "latest_repair_id": 734650698524280,
  "rerun_tasks": ["load_silver"],
  "rerun_dependent_tasks": true
}'

# New run of a subset: load_silver plus everything downstream
databricks bundle run --only load_silver+ orders_job
